public class Solution {
    // Expande com R; enquanto a soma atende, encolhe com L. Cada índice entra e sai uma vez: O(n).
    static int menorJanela(int alvo, int[] nums) {
        int melhor = Integer.MAX_VALUE;
        long soma = 0;
        int l = 0;
        for (int r = 0; r < nums.length; r++) {
            soma += nums[r];
            while (soma >= alvo) {
                melhor = Math.min(melhor, r - l + 1);
                soma -= nums[l++];
            }
        }
        return melhor == Integer.MAX_VALUE ? 0 : melhor;
    }
}

