import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplo() {
        assertEquals(2, Solution.menorJanela(7, new int[]{2, 3, 1, 2, 4, 3}));
    }

    @Test void umElementoBasta() {
        assertEquals(1, Solution.menorJanela(4, new int[]{1, 4, 4}));
    }

    @Test void impossivel() {
        assertEquals(0, Solution.menorJanela(100, new int[]{1, 2, 3}));
        assertEquals(0, Solution.menorJanela(1, new int[]{}));
    }

    @Test void grande() {
        int[] a = new int[100_000];
        java.util.Arrays.fill(a, 1);
        a[50_000] = 1000;
        assertEquals(1, Solution.menorJanela(1000, a));
        assertEquals(100_000, Solution.menorJanela(100_999, a));
    }
}

