import java.util.HashMap;
import java.util.Map;

public class Solution {
    // soma(i..j) = pre[j+1] - pre[i]: conte quantos prefixos anteriores valem pre - k. O(n).
    static long contarSubarrays(int[] nums, int k) {
        Map<Long, Long> freq = new HashMap<>();
        freq.put(0L, 1L);
        long pre = 0, total = 0;
        for (int x : nums) {
            pre += x;
            total += freq.getOrDefault(pre - k, 0L);
            freq.merge(pre, 1L, Long::sum);
        }
        return total;
    }
}

