import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        assertEquals(2, Solution.contarSubarrays(new int[]{1, 1, 1}, 2));
        assertEquals(4, Solution.contarSubarrays(new int[]{1, -1, 1, -1}, 0));
    }

    @Test void negativos() {
        assertEquals(4, Solution.contarSubarrays(new int[]{3, 4, 7, 2, -3, 1, 4, 2}, 7));
    }

    @Test void vazioEUnico() {
        assertEquals(0, Solution.contarSubarrays(new int[]{}, 0));
        assertEquals(1, Solution.contarSubarrays(new int[]{5}, 5));
    }

    @Test void grandeDeZeros() {
        int[] a = new int[100_000];
        assertEquals(100_000L * 100_001 / 2, Solution.contarSubarrays(a, 0));
    }
}
